package com.example.starter.sync.domain;

/**
 * 消息丢弃原因码（稳定枚举，用于定位）。
 */
public enum DiscardReason {
    /** 同一传感器内消息ID重复，重放幂等丢弃。 */
    DUPLICATE_MESSAGE,
    /** 校正时戳低于水位线减去迟到容忍，过晚到达。 */
    LATE_MESSAGE,
    /** 校正时戳已落入某个已提交融合帧的窗口，不允许修改历史帧。 */
    FRAME_ALREADY_COMMITTED
}

package com.example.starter.sync.domain;

/**
 * 消息接收结果。status 区分接受与丢弃；丢弃时 reason 非空。
 */
public record IngestOutcome(
        Status status,
        SensorSample sample,
        DiscardReason reason) {

    public enum Status {
        ACCEPTED,
        DISCARDED
    }

    public static IngestOutcome accepted(SensorSample sample) {
        return new IngestOutcome(Status.ACCEPTED, sample, null);
    }

    public static IngestOutcome discarded(SensorSample sample, DiscardReason reason) {
        return new IngestOutcome(Status.DISCARDED, sample, reason);
    }

    public boolean isAccepted() {
        return status == Status.ACCEPTED;
    }
}

package com.example.starter.sync;

/**
 * 业务稳定错误码。缺帧、超出窗口、无法插值、重复提交等均以此枚举对外暴露。
 */
public enum SyncErrorCode {
    /** 目标时刻已存在已提交融合帧。 */
    FRAME_ALREADY_COMMITTED,
    /** 指定时刻不存在已提交融合帧。 */
    FRAME_NOT_FOUND,
    /** 必需传感器没有任何样本，缺帧。 */
    MISSING_INPUT,
    /** 传感器有样本但全部超出配对窗口，且缺少另一侧样本无法插值。 */
    OUT_OF_WINDOW,
    /** 窗口内无样本，两侧样本存在但跨度超出插值上限。 */
    CANNOT_INTERPOLATE,
    /** 漂移参数版本不合法（必须大于当前版本）。 */
    INVALID_DRIFT_VERSION,
    /** 请求参数不合法。 */
    BAD_REQUEST
}

package com.example.starter.sync;

/**
 * 携带稳定错误码的业务异常。
 */
public class SyncException extends RuntimeException {

    private final SyncErrorCode code;

    public SyncException(SyncErrorCode code, String message) {
        super(message);
        this.code = code;
    }

    public SyncErrorCode code() {
        return code;
    }
}

