                }
                default -> {
                    // MESSAGE_DUPLICATE / MESSAGE_DISCARDED 为派生记录，重放时无需处理
                }
            }
        }
        throw new SyncException(SyncErrorCode.FRAME_NOT_FOUND,
                "no committed fusion frame at target " + targetTs + " in event log");
    }
}

